'use strict';
function openModal(title,content,eyebrow='AIC ACADEMY SHANZU'){
  $('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-content').innerHTML=content;
  if(!$('#modal').open)$('#modal').showModal();
  requestAnimationFrame(()=>{const el=$('#modal-content input:not([type=hidden]):not([readonly]), #modal-content select, #modal-content textarea');if(el)el.focus({preventScroll:true});});
}
function closeModal(){$('#modal').close();}
function formError(form,message){const el=$('.form-error',form);if(el){el.textContent=message;el.scrollIntoView({block:'nearest'});}else toast(message,true);}
function field(form,name){return String(new FormData(form).get(name)||'').trim();}
function centsValue(form,name,{zero=false}={}){const raw=field(form,name),n=Number(raw);if(!raw||!Number.isFinite(n)||n<0||(!zero&&n===0)||n>1000000000)throw Error('Enter a valid '+(zero?'non-negative ':'positive ')+'KSh amount.');const cents=Math.round(n*100);if(!Number.isSafeInteger(cents))throw Error('The amount is too large.');return cents;}
function intField(form,name,min=0,max=1000000){const n=Number(field(form,name));if(!Number.isSafeInteger(n)||n<min||n>max)throw Error(`Enter a whole number between ${min} and ${max}.`);return n;}
function dateField(form,name){const v=field(form,name);if(!validDate(v))throw Error('Choose a valid date.');return v;}
function hidden(name,value){return `<input type="hidden" name="${name}" value="${esc(value)}">`;}
function input(name,label,value='',type='text',attrs=''){return `<div class="form-field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function select(name,label,values,current,labeler=v=>v,attrs=''){return `<div class="form-field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${attrs}>${options(values,current,labeler)}</select></div>`;}
function textarea(name,label,value='',attrs=''){return `<div class="form-field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" rows="4" ${attrs}>${esc(value)}</textarea></div>`;}
function formActions(label='Save record'){return `<div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button secondary" data-action="close-modal">Cancel</button><button type="submit" class="button primary">${icon('check')}${label}</button></div>`;}
function studentSelect(current='',all=false){return select('studentId','Learner',all?state.students:state.students.filter(s=>s.status==='Active'||s.id===current),current,s=>s.name+' · '+s.grade+' · '+s.id,'required');}
function openForm(type,id='',prefill=''){
  if(type==='payment'){
    const available=currentInvoices().filter(i=>balance(i)>0);if(!available.length){openModal('All fees are settled',empty('No outstanding invoices','Create an invoice before recording a payment.',btn('New invoice','add-invoice')));return;}
    const inv=available.find(i=>i.id===prefill)||available[0];
    openModal('Record a payment',`<form data-form="payment"><div class="form-summary"><span>Invoice balance</span><b class="money" id="payment-balance">${money(balance(inv))}</b></div><div class="form-grid"><div class="form-field full"><label for="f-invoiceId">Fee statement</label><select id="f-invoiceId" name="invoiceId" required>${options(available,inv.id,i=>student(i.studentId).name+' · '+i.id+' · '+money(balance(i)))}</select></div>${input('amount','Amount received (KSh)',(balance(inv)/100).toFixed(2),'number',`required min="0.01" max="${balance(inv)/100}" step="0.01"`)}${input('date','Payment date',today(),'date',`required max="${today()}"`)}${select('method','Payment method',['M-Pesa','Bank','Cash','Cheque'],'M-Pesa')}${input('reference','Transaction / receipt reference','','text','required maxlength="80" placeholder="e.g. M-Pesa transaction code"')}<div class="form-field full"><small>Posts to the matching school account. Bursary credits are recorded from the Bursaries page. No money is moved by this demo.</small></div></div>${formActions('Save payment')}</form>`,'FEE COLLECTION');return;
  }
  if(type==='student'){
    const s=student(id)||{name:'',grade:'Grade 1',stream:'Bahari',guardian:'',phone:'',admission:today(),status:'Active',notes:''};
    openModal(id?'Edit learner':'Admit a learner',`<form data-form="student">${hidden('id',id)}<div class="form-grid">${input('name','Full name',s.name,'text','required maxlength="80"')}${input('guardian','Parent / guardian',s.guardian,'text','required maxlength="80"')}${select('grade','Class',D.grades,s.grade)}${select('stream','Stream',['Bahari','Kijani'],s.stream)}${input('admission','Admission date',s.admission,'date',`required max="${today()}"`)}${input('phone','Guardian phone (optional)',s.phone,'tel','maxlength="25" placeholder="+254…"')}${select('status','Enrolment status',['Active','Inactive'],s.status)}${textarea('notes','Notes (optional)',s.notes,'maxlength="500"')}<div class="form-field full"><small>${id?'Admission number: '+esc(id):'An admission number is generated automatically.'} Use sample details on the public demo.</small></div></div>${formActions(id?'Save learner':'Admit learner')}</form>`,'LEARNER REGISTER');return;
  }
  if(type==='invoice'){
    if(!state.students.some(s=>s.status==='Active')){toast('Admit an active learner first.',true);return;}
    openModal('Issue a fee invoice',`<form data-form="invoice"><div class="form-grid">${studentSelect(prefill)}${input('amount','Invoice total (KSh)',(state.settings.defaultFee/100).toFixed(2),'number','required min="0.01" max="10000000" step="0.01"')}${input('description','Fee description','Tuition · '+state.settings.term,'text','required maxlength="120"')}${select('term','School term',['Term 1','Term 2','Term 3'],state.settings.term)}${input('year','Academic year',state.settings.year,'number','required min="2020" max="2100"')}${input('issued','Issue date',today(),'date','required')}${input('due','Due date',state.settings.payday,'date','required')}<div class="form-field full"><small>For transport or lunch charges, issue a separate invoice. Existing invoices are never changed automatically.</small></div></div>${formActions('Issue invoice')}</form>`,'FEES & INVOICES');return;
  }
  if(type==='expense'){
    openModal('Record an expense',`<form data-form="expense"><div class="form-grid"><div class="form-field full"><label for="f-description">What was this expense for?</label><input id="f-description" name="description" required maxlength="140" placeholder="e.g. Classroom reading materials"></div>${select('category','Category',D.categories,'Learning materials')}${input('amount','Amount (KSh)','','number','required min="0.01" max="10000000" step="0.01"')}${input('date','Expense date',today(),'date',`required max="${today()}"`)}${select('account','Paid from',state.accounts,'Bank',a=>a.name+' · '+whole(accountBalance(a.id)))}${input('vendor','Supplier / payee','','text','maxlength="100" placeholder="Optional"')}<div class="form-field full"><small>This reduces the selected account balance immediately.</small></div></div>${formActions('Save expense')}</form>`,'SCHOOL SPENDING');return;
  }
  if(type==='staff'){
    const s=state.staff.find(s=>s.id===id)||{name:'',role:'',gross:0,paye:0,nssf:0,shif:0,housing:0,phone:''};
    openModal(id?'Edit staff & deductions':'Add a staff member',`<form data-form="staff">${hidden('id',id)}<div class="form-grid">${input('name','Staff name',s.name,'text','required maxlength="80"')}${input('role','Role',s.role,'text','required maxlength="80"')}${input('gross','Monthly gross (KSh)',s.gross/100,'number','required min="0.01" step="0.01" max="10000000"')}${input('paye','PAYE (KSh)',s.paye/100,'number','required min="0" step="0.01"')}${input('nssf','NSSF employee deduction (KSh)',s.nssf/100,'number','required min="0" step="0.01"')}${input('shif','SHIF (KSh)',s.shif/100,'number','required min="0" step="0.01"')}${input('housing','Affordable Housing Levy (KSh)',s.housing/100,'number','required min="0" step="0.01"')}${input('phone','Phone (optional)',s.phone,'tel','maxlength="25"')}<div class="form-field full"><small>Enter approved deduction amounts, not percentages. Rates are not calculated or certified by this demo. Employer contributions are not included.</small></div></div>${formActions('Save staff member')}</form>`,'PEOPLE & PAYROLL');return;
  }
  if(type==='assessment'){
    const a=state.assessments.find(a=>a.id===id)||{studentId:prefill,area:'Mathematics',strand:'',level:'ME',comment:'',date:today()};
    openModal(id?'Edit learning observation':'Record a learning observation',`<form data-form="assessment">${hidden('id',id)}<div class="form-grid">${studentSelect(a.studentId)}${select('area','Learning area',D.areas,a.area)}<div class="form-field full"><label for="f-strand">Strand / skill observed</label><input id="f-strand" name="strand" required maxlength="120" value="${esc(a.strand)}" placeholder="e.g. Number operations"></div>${select('level','Competency level',Object.keys(D.levels),a.level,k=>k+' · '+D.levels[k])}${input('date','Observation date',a.date,'date',`required max="${today()}"`)}${textarea('comment','Evidence & next steps',a.comment,'required maxlength="800" placeholder="What can the learner do? What support comes next?"')}<div class="form-field full"><small>${esc(state.settings.term)} · ${state.settings.year}. This observation is added to the learner’s progress report.</small></div></div>${formActions('Save observation')}</form>`,'COMPETENCY-BASED LEARNING');return;
  }
  if(type==='bursary'){
    const a=state.awards.find(a=>a.id===id)||{studentId:prefill,amount:0,source:'NG-CDF',reference:'',status:'Requested'};
    openModal(id?'Edit bursary request':'New bursary request',`<form data-form="bursary">${hidden('id',id)}<div class="form-grid">${studentSelect(a.studentId)}${input('amount','Requested amount (KSh)',a.amount?a.amount/100:'','number','required min="0.01" max="10000000" step="0.01"')}${select('source','Funder',['NG-CDF','County bursary','School bursary','Other'],a.source)}${select('status','Decision',['Requested','Approved'],a.status)}${input('reference','Award / application reference',a.reference,'text','maxlength="80" placeholder="Optional until approved"')}<div class="form-field full"><small>This records an application or decision only. Record the actual disbursement separately to credit school fees.</small></div></div>${formActions('Save bursary')}</form>`,'BURSARIES & SUPPORT');return;
  }
  if(type==='route'){
    const r=state.routes.find(r=>r.id===id)||{name:'',area:'',capacity:14,fare:350000,driver:''};
    openModal(id?'Manage school route':'Add a school route',`<form data-form="route">${hidden('id',id)}<div class="form-grid">${input('name','Route name',r.name,'text','required maxlength="80"')}${input('area','Areas served',r.area,'text','required maxlength="140"')}${input('capacity','Learner capacity',r.capacity,'number','required min="1" max="100" step="1"')}${input('fare','Monthly route fare (KSh)',r.fare/100,'number','required min="0" max="1000000" step="0.01"')}${input('driver','Driver / transport contact',r.driver,'text','maxlength="120" placeholder="Optional"')}<div class="form-field full"><small>Capacity cannot be lower than the number of active learners already assigned.</small></div></div>${formActions('Save route')}</form>`,'SCHOOL TRANSPORT');return;
  }
  if(type==='assign'){
    const s=student(id)||state.students.find(s=>s.status==='Active');if(!s){toast('Admit an active learner first.',true);return;}
    openModal('Assign a learner to transport',`<form data-form="assign"><div class="form-grid">${studentSelect(s.id)}${select('route','School route',['',...state.routes.map(r=>r.id)],s.route,r=>r?state.routes.find(x=>x.id===r).name:'Not using school transport')}${input('stop','Pick-up / drop-off stop',s.stop,'text','maxlength="120" placeholder="e.g. Shanzu junction"')}<div class="form-field full"><small>Guardian transport permissions should be confirmed separately. This assignment does not create a fee invoice.</small></div></div>${formActions('Save assignment')}</form>`,'SCHOOL TRANSPORT');return;
  }
  if(type==='stock'){
    const s=state.stock.find(s=>s.id===id)||{name:'',category:'Learning materials',unit:'pieces',quantity:0,reorder:10};
    openModal(id?'Edit stock item':'Add a stock item',`<form data-form="stock">${hidden('id',id)}<div class="form-grid"><div class="form-field full"><label for="f-name">Item name</label><input id="f-name" name="name" required maxlength="100" value="${esc(s.name)}"></div>${input('category','Category',s.category,'text','required maxlength="60"')}${input('unit','Unit',s.unit,'text','required maxlength="20" placeholder="pieces, kg, books…"')}${input('quantity',id?'On hand (use Receive / Issue)':'Opening quantity',s.quantity,'number',`required min="0" max="1000000" step="1" ${id?'readonly':''}`)}${input('reorder','Reorder level',s.reorder,'number','required min="0" max="1000000" step="1"')}<div class="form-field full"><small>An item at or below its reorder level is flagged for replenishment.</small></div></div>${formActions('Save item')}</form>`,'SCHOOL STORE');return;
  }
  if(type==='stock-move'){
    const s=state.stock.find(s=>s.id===id),direction=Number(prefill);if(!s)return;
    openModal(direction>0?'Receive stock':'Issue stock',`<form data-form="stock-move">${hidden('id',id)}${hidden('direction',direction)}<div class="form-summary"><span>${esc(s.name)}</span><b>${s.quantity} ${esc(s.unit)} on hand</b></div><div class="form-grid">${input('quantity','Quantity '+esc(s.unit),'','number',`required min="1" max="${direction<0?s.quantity:1000000}" step="1"`)}${input('date','Movement date',today(),'date',`required max="${today()}"`)}${input('reason','Reason / issued to','','text','required maxlength="140" placeholder="e.g. Supplier delivery / Grade 7 classroom"')}</div>${formActions(direction>0?'Receive stock':'Issue stock')}</form>`,'STOCK MOVEMENT');return;
  }
  if(type==='message'){
    const m=state.messages.find(m=>m.id===id)||{title:'',audience:'All guardians',body:'',status:'Draft'};
    openModal(id?'Edit school notice':'Compose a school notice',`<form data-form="message">${hidden('id',id)}<div class="form-grid">${input('title','Notice title',m.title,'text','required maxlength="100"')}${select('audience','Intended audience',['All guardians','Fees outstanding','Absent today',...D.grades],m.audience)}${select('template','Start from a template',['','fee','attendance','meeting'],'',v=>({'':'Choose a template (optional)',fee:'Fee reminder',attendance:'Attendance follow-up',meeting:'Parent meeting'})[v])}${select('status','Status',['Draft','Prepared'],m.status)}${textarea('body','Message',m.body,'required maxlength="3000" placeholder="Write a clear, friendly message…"')}<div class="form-field full"><small>Preparing a notice does not send it. You can copy or print it after saving.</small></div></div>${formActions('Save notice')}</form>`,'SCHOOL COMMUNICATIONS');return;
  }
  if(type==='transfer'){
    openModal('Transfer between accounts',`<form data-form="transfer"><div class="form-grid">${select('from','From account',state.accounts,'Bank',a=>a.name+' · '+whole(accountBalance(a.id)))}${select('to','To account',state.accounts,'M-Pesa',a=>a.name)}${input('amount','Amount (KSh)','','number','required min="0.01" max="10000000" step="0.01"')}${input('date','Transfer date',today(),'date',`required max="${today()}"`)}${input('reference','Reference / note','','text','maxlength="120" placeholder="Optional"')}<div class="form-field full"><small>Record a transfer you have already made. This does not instruct a bank or M-Pesa to move money.</small></div></div>${formActions('Record transfer')}</form>`,'SCHOOL ACCOUNTS');return;
  }
  if(type==='opening'){
    openModal('Edit opening balances',`<form data-form="opening"><div class="form-grid">${state.accounts.map(a=>input('opening-'+a.id,esc(a.name)+' (KSh)',a.opening/100,'number','required min="0" max="1000000000" step="0.01"')).join('')}<div class="form-field full"><small>All recorded receipts, expenses and transfers are then applied. No account may have a negative resulting balance.</small></div></div>${formActions('Save opening balances')}</form>`,'SCHOOL ACCOUNTS');return;
  }
  if(type==='pay-staff'){
    const s=state.staff.find(s=>s.id===id);if(!s||staffPaid(id))return;
    openModal('Record salary payment',`<form data-form="pay-staff">${hidden('id',id)}${hidden('period',ui.payrollPeriod)}<div class="form-summary"><span>${esc(s.name)} · ${monthLabel(ui.payrollPeriod)}</span><b class="money">${money(netPay(s))}</b></div><div class="form-grid">${select('account','Paid from',state.accounts,'Bank',a=>a.name+' · '+whole(accountBalance(a.id)))}${input('date','Payment date',today().startsWith(ui.payrollPeriod)?today():ui.payrollPeriod+'-01','date','required')}${input('reference','Payment reference','','text','required maxlength="80"')}<div class="form-field full"><small>Creates one salary expense and a payslip using the current entered deductions. Confirm the transfer with your bank separately.</small></div></div>${formActions('Mark salary paid')}</form>`,'PAYROLL');return;
  }
}
function openStudentDetail(id){const s=student(id);if(!s)return;const inv=currentInvoices().filter(i=>i.studentId===id),r=state.routes.find(r=>r.id===s.route);openModal('Learner profile',`<div class="detail-heading">${who(s,false)}</div><dl class="detail-grid"><div><dt>Admission number</dt><dd>${esc(s.id)}</dd></div><div><dt>Enrolment</dt><dd>${badge(s.status,s.status==='Active'?'green':'gray')}</dd></div><div><dt>Parent / guardian</dt><dd>${esc(s.guardian)}</dd></div><div><dt>Phone</dt><dd>${esc(s.phone||'Not provided')}</dd></div><div><dt>Admitted</dt><dd>${dateLabel(s.admission)}</dd></div><div><dt>Transport</dt><dd>${esc(r?.name||'Not assigned')}</dd></div></dl>${s.notes?`<div class="notice">${icon('info')}<div>${esc(s.notes)}</div></div>`:''}<div class="detail-section"><h3>${esc(state.settings.term)} fee statements</h3>${inv.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Balance</th><th></th></tr></thead><tbody>${inv.map(i=>`<tr><td>${esc(i.id)}<small class="muted" style="display:block">${esc(i.description)}</small></td><td class="money">${money(balance(i))}</td><td><button class="text-button" data-action="invoice-detail" data-id="${esc(i.id)}">View ${icon('right')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No invoice this term','Issue a fee statement when ready.')}</div><div class="form-actions" style="flex-wrap:wrap">${btn('Edit learner','edit-student','edit','secondary',`data-id="${esc(id)}"`)}${btn('New invoice','invoice-for','receipt','secondary',`data-id="${esc(id)}"`)}${btn('CBC report','cbc-report','print','primary',`data-id="${esc(id)}"`)}</div>`,'LEARNER PROFILE');}
function openInvoiceDetail(id){const i=invoice(id);if(!i)return;const receipts=state.payments.filter(p=>p.invoiceId===id).sort((a,b)=>b.date.localeCompare(a.date));openModal('Fee statement',`<div class="detail-heading">${who(student(i.studentId),false)}</div><dl class="detail-grid"><div><dt>Statement</dt><dd>${esc(i.id)}</dd></div><div><dt>Term</dt><dd>${esc(i.term)} · ${i.year}</dd></div><div><dt>Issued</dt><dd>${dateLabel(i.issued)}</dd></div><div><dt>Due</dt><dd>${dateLabel(i.due)}</dd></div><div><dt>Invoice total</dt><dd class="money">${money(i.amount)}</dd></div><div><dt>Balance</dt><dd class="money">${money(balance(i))} ${feeBadge(i)}</dd></div></dl><p class="muted" style="font-size:12px">${esc(i.description)}</p><div class="detail-section"><h3>Payments received · ${money(paid(i))}</h3>${receipts.length?`<div class="table-wrap"><table><thead><tr><th>Date / method</th><th>Amount</th><th></th></tr></thead><tbody>${receipts.map(p=>`<tr><td>${dateLabel(p.date)} · ${esc(p.method)}<small class="muted" style="display:block">${esc(p.reference)}</small></td><td class="money">${money(p.amount)}</td><td><button class="text-button" data-action="receipt" data-id="${esc(p.id)}" aria-label="Print receipt">${icon('print')}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted" style="font-size:12px">No payment has been recorded.</p>'}</div><div class="form-actions">${btn('Print statement','print-invoice','print','secondary',`data-id="${esc(id)}"`)}${balance(i)>0?btn('Record payment','payment-for','plus','primary',`data-id="${esc(id)}"`):badge('Settled in full','green')}</div>`,'FEES & INVOICES');}
function openBursaryDetail(id){const a=state.awards.find(a=>a.id===id);if(!a)return;const available=currentInvoices().filter(i=>i.studentId===a.studentId&&balance(i)>=a.amount);openModal('Bursary details',`<div class="detail-heading">${who(student(a.studentId),false)}</div><dl class="detail-grid"><div><dt>Funder</dt><dd>${esc(a.source)}</dd></div><div><dt>Amount</dt><dd class="money">${money(a.amount)}</dd></div><div><dt>Status</dt><dd>${badge(a.status,a.status==='Disbursed'?'green':'amber')}</dd></div><div><dt>Reference</dt><dd>${esc(a.reference||'Not assigned')}</dd></div></dl>${a.status==='Requested'?`<div class="notice">${icon('info')}<div>Record the funder’s decision here. Approval does not credit the learner’s fees.</div></div><div class="form-actions">${btn('Decline request','bursary-decision','x','secondary',`data-id="${id}" data-status="Declined"`)}${btn('Record approval','bursary-decision','check','primary',`data-id="${id}" data-status="Approved"`)}</div>`:a.status==='Approved'?available.length?`<form data-form="disburse">${hidden('id',id)}<div class="form-summary"><span>Ready to disburse</span><b>${money(a.amount)}</b></div><div class="form-grid"><div class="form-field full"><label for="f-invoiceId">Credit fee statement</label><select id="f-invoiceId" name="invoiceId" required>${options(available,available[0].id,i=>i.id+' · balance '+money(balance(i)))}</select></div>${input('date','Disbursement date',today(),'date',`required max="${today()}"`)}${select('account','Received into',state.accounts,'Bank',a=>a.name)}${input('reference','Funder payment reference',a.reference,'text','required maxlength="80"')}<div class="form-field full"><small>This posts a bursary receipt once and reduces the invoice balance.</small></div></div>${formActions('Record disbursement')}</form>`:notice('No current fee statement can cover this award. Issue or adjust the learner’s fee statement before recording disbursement.',true):a.status==='Disbursed'?`<div class="form-actions">${btn('View fee receipt','receipt','receipt','primary',`data-id="${esc(a.paymentId)}"`)}</div>`:notice('This request was declined. No fee credit was posted.')}`,'BURSARIES & SUPPORT');}
function audienceCount(audience){if(audience==='All guardians')return state.students.filter(s=>s.status==='Active').length;if(audience==='Fees outstanding')return totals().unpaid;if(audience==='Absent today')return Object.entries(state.attendance[today()]||{}).filter(([id,v])=>v==='Absent'&&student(id)?.status==='Active').length;return state.students.filter(s=>s.grade===audience&&s.status==='Active').length;}
function openPaymentDetail(id){const p=state.payments.find(p=>p.id===id);if(!p)return;const i=invoice(p.invoiceId);openModal('Payment record',`<div class="detail-heading">${who(student(p.studentId),false)}</div><div class="print-total money" style="font-size:30px;margin:20px 0">${money(p.amount)}</div><dl class="detail-grid"><div><dt>Received</dt><dd>${dateLabel(p.date)}</dd></div><div><dt>Method</dt><dd>${esc(p.method)}</dd></div><div><dt>Reference</dt><dd>${esc(p.reference)}</dd></div><div><dt>Account</dt><dd>${esc(p.account)}</dd></div><div><dt>Invoice</dt><dd>${esc(i.id)}</dd></div><div><dt>Invoice balance</dt><dd>${money(balance(i))}</dd></div></dl><div class="form-actions">${btn('View statement','invoice-detail','receipt','secondary',`data-id="${esc(i.id)}"`)}${btn('Print receipt','receipt','print','primary',`data-id="${esc(id)}"`)}</div>`,'FEE COLLECTION');}
function openMessageDetail(id){const m=state.messages.find(m=>m.id===id);if(!m)return;openModal(m.title,`${badge(m.status,m.status==='Prepared'?'green':'amber')} <span class="muted" style="font-size:11px">${esc(m.audience)} · ${audienceCount(m.audience)} intended recipients</span><div class="message-preview">${esc(m.body)}</div>${notice('This is a prepared notice. Nothing has been sent. Copy or print it for your own channel.')}<div class="form-actions" style="flex-wrap:wrap">${btn('Copy text','copy-message','copy','secondary',`data-id="${id}"`)}${btn('Print notice','print-message','print','secondary',`data-id="${id}"`)}${m.status==='Draft'?btn('Mark prepared','prepare-message','check','primary',`data-id="${id}"`):btn('Edit notice','edit-message','edit','primary',`data-id="${id}"`)}</div>`,'SCHOOL COMMUNICATIONS');}
const templates={
 fee:'Dear parent or guardian,\n\nThis is a friendly reminder to settle the outstanding school fees for the current term. Please contact the school office to discuss a payment arrangement or bursary support.\n\nThank you for partnering with '+state.settings.school+'.',
 attendance:'Dear parent or guardian,\n\nOur register shows that your learner was absent today. Please contact the class teacher to confirm the reason and discuss any support needed for a smooth return to school.\n\nThank you,\n'+state.settings.school,
 meeting:'Dear parent or guardian,\n\nYou are invited to a parent and teacher meeting at the school. Please contact the office to confirm a convenient appointment.\n\nWe look forward to seeing you.\n'+state.settings.school
};
function handleSubmit(event){
  const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();
  try{
    const type=form.dataset.form,id=field(form,'id');
    if(type==='payment'){
      const inv=invoice(field(form,'invoiceId')),amount=centsValue(form,'amount'),date=dateField(form,'date'),method=field(form,'method'),reference=field(form,'reference');
      if(!inv||balance(inv)<=0)throw Error('Choose an invoice with an outstanding balance.');
      if(amount>balance(inv))throw Error('The payment exceeds the outstanding invoice balance.');
      if(date>today()||date<inv.issued)throw Error('Use a payment date between the invoice issue date and today.');
      if(!reference)throw Error('Enter a transaction or receipt reference.');
      if(!['M-Pesa','Bank','Cash','Cheque'].includes(method))throw Error('Choose a valid payment method.');
      const payment={id:uid('PAY'),invoiceId:inv.id,studentId:inv.studentId,amount,date,method,reference,account:method==='M-Pesa'?'M-Pesa':method==='Cash'?'Cash':'Bank',note:''};
      commit(s=>s.payments.push(payment),'Payment recorded · '+money(amount));closeModal();return;
    }
    if(type==='student'){
      const name=field(form,'name'),guardian=field(form,'guardian');if(!name||!guardian)throw Error('Enter the learner and guardian names.');
      const values={name,guardian,grade:field(form,'grade'),stream:field(form,'stream'),phone:field(form,'phone'),admission:dateField(form,'admission'),status:field(form,'status'),notes:field(form,'notes')};
      if(values.admission>today())throw Error('Admission cannot be in the future.');
      commit(s=>{if(id)Object.assign(s.students.find(x=>x.id===id),values);else s.students.push({id:uid('AIC'),...values,route:'',stop:''});},id?'Learner details updated':'Learner admitted · '+name);closeModal();return;
    }
    if(type==='invoice'){
      const st=student(field(form,'studentId')),amount=centsValue(form,'amount'),issued=dateField(form,'issued'),due=dateField(form,'due'),description=field(form,'description'),year=intField(form,'year',2020,2100),term=field(form,'term');
      if(!st||!description||due<issued)throw Error('Choose a learner and description; the due date must not precede the issue date.');
      const inv={id:uid('INV'),studentId:st.id,amount,issued,due,description,year,term};commit(s=>s.invoices.push(inv),'Invoice issued · '+st.name);closeModal();return;
    }
    if(type==='expense'){
      const amount=centsValue(form,'amount'),account=field(form,'account'),description=field(form,'description'),date=dateField(form,'date');if(!description||date>today())throw Error('Enter a description and a date no later than today.');if(amount>accountBalance(account))throw Error('This expense exceeds the selected account balance.');
      commit(s=>s.expenses.push({id:uid('EXP'),amount,account,description,date,category:field(form,'category'),vendor:field(form,'vendor')}),'Expense recorded · '+money(amount));closeModal();return;
    }
    if(type==='staff'){
      const name=field(form,'name'),role=field(form,'role');if(!name||!role)throw Error('Enter the staff name and role.');const values={name,role,gross:centsValue(form,'gross'),paye:centsValue(form,'paye',{zero:true}),nssf:centsValue(form,'nssf',{zero:true}),shif:centsValue(form,'shif',{zero:true}),housing:centsValue(form,'housing',{zero:true}),phone:field(form,'phone')};if(netPay(values)<0)throw Error('Total deductions cannot exceed gross pay.');
      commit(s=>{if(id)Object.assign(s.staff.find(x=>x.id===id),values);else s.staff.push({id:uid('STF'),...values,status:'Pending',paidDate:''});},'Staff payroll details saved');closeModal();return;
    }
    if(type==='assessment'){
      const studentId=field(form,'studentId'),strand=field(form,'strand'),comment=field(form,'comment'),date=dateField(form,'date');if(!student(studentId)||!strand||!comment||date>today())throw Error('Choose a learner, the skill observed, evidence and a valid observation date.');
      const values={studentId,strand,comment,date,area:field(form,'area'),level:field(form,'level'),term:state.settings.term,year:state.settings.year};commit(s=>{if(id)Object.assign(s.assessments.find(x=>x.id===id),values);else s.assessments.push({id:uid('CBC'),...values});},'CBC observation saved');closeModal();return;
    }
    if(type==='bursary'){
      const studentId=field(form,'studentId'),amount=centsValue(form,'amount'),status=field(form,'status'),reference=field(form,'reference');if(!student(studentId))throw Error('Choose a learner.');if(status==='Approved'&&!reference)throw Error('Enter the funder’s award reference before recording approval.');
      const values={studentId,amount,status,reference,source:field(form,'source')};commit(s=>{if(id){const a=s.awards.find(x=>x.id===id);if(a.status==='Disbursed')throw Error('A disbursed award cannot be edited.');Object.assign(a,values);}else s.awards.push({id:uid('BUR'),...values,date:today(),paymentId:''});},'Bursary request saved');closeModal();return;
    }
    if(type==='route'){
      const name=field(form,'name'),area=field(form,'area'),capacity=intField(form,'capacity',1,100),fare=centsValue(form,'fare',{zero:true});if(!name||!area)throw Error('Enter a route name and the areas served.');if(id&&capacity<state.students.filter(s=>s.route===id&&s.status==='Active').length)throw Error('Capacity is below the number of learners already assigned.');
      const values={name,area,capacity,fare,driver:field(form,'driver')};commit(s=>{if(id)Object.assign(s.routes.find(x=>x.id===id),values);else s.routes.push({id:uid('RT'),...values});},'School route saved');closeModal();return;
    }
    if(type==='assign'){
      const st=student(field(form,'studentId')),route=field(form,'route'),stop=field(form,'stop');if(!st)throw Error('Choose a learner.');if(route){const r=state.routes.find(r=>r.id===route);if(!r||!stop)throw Error('Choose a valid route and enter the pick-up stop.');if(st.route!==route&&state.students.filter(s=>s.route===route&&s.status==='Active').length>=r.capacity)throw Error('This route is full. Choose another route or increase its capacity.');}
      commit(s=>{const x=s.students.find(s=>s.id===st.id);x.route=route;x.stop=route?stop:'';},'Transport assignment saved');closeModal();return;
    }
    if(type==='stock'){
      const name=field(form,'name'),category=field(form,'category'),unit=field(form,'unit'),quantity=intField(form,'quantity'),reorder=intField(form,'reorder');if(!name||!category||!unit)throw Error('Enter the item name, category and unit.');
      commit(s=>{if(id)Object.assign(s.stock.find(x=>x.id===id),{name,category,unit,reorder});else{const itemId=uid('ITM');s.stock.push({id:itemId,name,category,unit,quantity,reorder});s.stockMoves.push({id:uid('MOV'),itemId,quantity,date:today(),reason:'Opening stock'});}},'Stock item saved');closeModal();return;
    }
    if(type==='stock-move'){
      const item=state.stock.find(s=>s.id===id),quantity=intField(form,'quantity',1),direction=Number(field(form,'direction')),date=dateField(form,'date'),reason=field(form,'reason');if(!item||!reason||date>today()||![1,-1].includes(direction))throw Error('Enter a quantity, reason and valid movement date.');if(direction<0&&quantity>item.quantity)throw Error('You cannot issue more than the quantity on hand.');
      commit(s=>{s.stock.find(x=>x.id===id).quantity+=direction*quantity;s.stockMoves.push({id:uid('MOV'),itemId:id,quantity:direction*quantity,date,reason});},direction>0?'Stock received':'Stock issued');closeModal();return;
    }
    if(type==='message'){
      const title=field(form,'title'),body=field(form,'body');if(!title||!body)throw Error('Enter a notice title and message.');const values={title,body,audience:field(form,'audience'),status:field(form,'status'),date:today()};commit(s=>{if(id)Object.assign(s.messages.find(x=>x.id===id),values);else s.messages.push({id:uid('MSG'),...values});},'School notice saved');closeModal();return;
    }
    if(type==='transfer'){
      const from=field(form,'from'),to=field(form,'to'),amount=centsValue(form,'amount'),date=dateField(form,'date');if(from===to)throw Error('Choose two different accounts.');if(amount>accountBalance(from))throw Error('The source account has insufficient funds.');if(date>today())throw Error('Record a transfer on or before today.');
      commit(s=>s.transfers.push({id:uid('TRF'),from,to,amount,date,reference:field(form,'reference')}),'Transfer recorded · '+money(amount));closeModal();return;
    }
    if(type==='opening'){
      const balances=Object.fromEntries(state.accounts.map(a=>[a.id,centsValue(form,'opening-'+a.id,{zero:true})]));commit(s=>s.accounts.forEach(a=>a.opening=balances[a.id]),'Opening balances updated');closeModal();return;
    }
    if(type==='settings'){
      const school=field(form,'school'),admin=field(form,'admin'),year=intField(form,'year',2020,2100),defaultFee=centsValue(form,'defaultFee'),payday=dateField(form,'payday');if(!school||!admin)throw Error('Enter the school and administrator names.');
      commit(s=>Object.assign(s.settings,{school,admin,year,defaultFee,payday,address:field(form,'address'),email:field(form,'email'),phone:field(form,'phone'),term:field(form,'term'),receiptFooter:field(form,'receiptFooter')}),'School profile saved');return;
    }
    if(type==='pay-staff'){
      const st=state.staff.find(s=>s.id===id),period=field(form,'period'),account=field(form,'account'),date=dateField(form,'date'),reference=field(form,'reference');if(!st||staffPaid(id,period))throw Error('This salary has already been recorded.');if(!reference||!date.startsWith(period)||date>today())throw Error('Use a payment reference and a date within the selected payroll period, no later than today.');const amount=netPay(st);if(amount<=0||amount>accountBalance(account))throw Error('Check the net pay and available account balance.');
      commit(s=>s.expenses.push({id:uid('SAL'),payrollId:id,payrollPeriod:period,category:'Salaries',description:'Salary · '+st.name+' · '+monthLabel(period),amount,date,vendor:st.name,account,reference,gross:st.gross,paye:st.paye,nssf:st.nssf,shif:st.shif,housing:st.housing}),'Salary recorded · '+st.name);closeModal();return;
    }
    if(type==='disburse'){
      const a=state.awards.find(a=>a.id===id),inv=invoice(field(form,'invoiceId')),date=dateField(form,'date'),reference=field(form,'reference'),account=field(form,'account');if(!a||a.status!=='Approved'||!inv||inv.studentId!==a.studentId)throw Error('Choose an approved award and the learner’s invoice.');if(a.amount>balance(inv))throw Error('The award exceeds this invoice balance.');if(!reference||date>today()||date<inv.issued)throw Error('Enter a funder reference and a valid disbursement date.');const paymentId=uid('PAY');
      commit(s=>{s.payments.push({id:paymentId,invoiceId:inv.id,studentId:a.studentId,amount:a.amount,date,method:'Bursary',reference,account,note:'Bursary disbursement'});const award=s.awards.find(x=>x.id===id);award.status='Disbursed';award.paymentId=paymentId;award.reference=reference;},'Bursary disbursed · fee statement credited');closeModal();return;
    }
    if(type==='bursary-approve'){
      const reference=field(form,'reference');if(!reference)throw Error('Enter the funder’s award reference.');commit(s=>{const a=s.awards.find(x=>x.id===id);if(a.status!=='Requested')throw Error('Only a requested award can be approved.');a.status='Approved';a.reference=reference;},'Bursary approval recorded');openBursaryDetail(id);return;
    }
    if(type==='reset'){
      if(field(form,'confirm')!=='RESET')throw Error('Type RESET to confirm.');state=D.seed();ui.attendanceDraft=null;ui.filters={};ui.pages={};loadWarning='';try{localStorage.setItem(STORAGE,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;}closeModal();navigate('overview');render();toast('Sample workspace restored.');return;
    }
  }catch(error){formError(form,error.message||'The record could not be saved. Please check your entries.');}
}
function dataset(type){
  const term=state.settings.term+' '+state.settings.year;
  if(type==='students')return {title:'Learner register',headers:['Admission','Learner','Class','Stream','Guardian','Phone','Status'],rows:state.students.filter(s=>{const f=ui.filters.students||{};return (!f.q||[s.name,s.id,s.guardian].join(' ').toLowerCase().includes(f.q.toLowerCase()))&&(!f.grade||s.grade===f.grade)&&(!f.status||s.status===f.status);}).map(s=>[s.id,s.name,s.grade,s.stream,s.guardian,s.phone,s.status])};
  if(type==='fees'||type==='invoices')return {title:'Fee statement report',subtitle:term,headers:['Admission','Learner','Class','Invoice','Due','Total (KSh)','Paid (KSh)','Balance (KSh)','Status'],money:[5,6,7],rows:currentInvoices().map(i=>{const s=student(i.studentId);return [s.id,s.name,s.grade,i.id,i.due,i.amount/100,paid(i)/100,balance(i)/100,invoiceStatus(i)];})};
  if(type==='payments')return {title:'Collections report',subtitle:term,headers:['Receipt','Learner','Invoice','Date','Method','Reference','Amount (KSh)'],money:[6],rows:currentPayments().map(p=>[p.id,student(p.studentId)?.name,p.invoiceId,p.date,p.method,p.reference,p.amount/100])};
  if(type==='expenses')return {title:'Expense report',headers:['Reference','Date','Category','Description','Supplier','Account','Amount (KSh)'],money:[6],rows:state.expenses.map(e=>[e.id,e.date,e.category,e.description,e.vendor,e.account,e.amount/100])};
  if(type==='payroll')return {title:'Payroll report',subtitle:monthLabel(ui.payrollPeriod)+' · manually entered deductions',headers:['Staff','Gross (KSh)','PAYE (KSh)','NSSF (KSh)','SHIF (KSh)','Levy (KSh)','Net (KSh)','Status'],money:[1,2,3,4,5,6],rows:state.staff.map(s=>{const e=state.expenses.find(e=>e.payrollId===s.id&&e.payrollPeriod===ui.payrollPeriod),v=e||s;return [s.name,v.gross/100,v.paye/100,v.nssf/100,v.shif/100,v.housing/100,netPay(v)/100,e?'Paid':'Pending'];})};
  if(type==='attendance'){const r=state.attendance[ui.attendanceDate]||{};return {title:'Attendance report',subtitle:dateLabel(ui.attendanceDate)+' · saved register',headers:['Admission','Learner','Class','Stream','Attendance'],rows:state.students.filter(s=>s.status==='Active').map(s=>[s.id,s.name,s.grade,s.stream,r[s.id]||'Unmarked'])};}
  if(type==='cbc')return {title:'CBC progress report',subtitle:term,headers:['Admission','Learner','Class','Learning area','Strand','Level','Evidence','Date'],rows:state.assessments.map(a=>{const s=student(a.studentId);return [s.id,s.name,s.grade,a.area,a.strand,a.level+' · '+D.levels[a.level],a.comment,a.date];})};
  if(type==='bursaries')return {title:'Bursary report',headers:['Reference','Learner','Funder','Award reference','Amount (KSh)','Status','Payment'],money:[4],rows:state.awards.map(a=>[a.id,student(a.studentId)?.name,a.source,a.reference,a.amount/100,a.status,a.paymentId])};
  if(type==='inventory')return {title:'Inventory report',headers:['Item','Category','Unit','On hand','Reorder level','Status'],rows:state.stock.map(s=>[s.name,s.category,s.unit,s.quantity,s.reorder,s.quantity<=s.reorder?'Low stock':'In stock'])};
  if(type==='transactions'){const rows=[];state.payments.forEach(p=>rows.push([p.date,'Fee receipt',p.reference,p.account,'',p.amount/100]));state.expenses.forEach(e=>rows.push([e.date,e.payrollId?'Salary':'Expense',e.reference||e.id,e.account,e.amount/100,'']));state.transfers.forEach(t=>{rows.push([t.date,'Transfer out',t.reference||t.id,t.from,t.amount/100,'']);rows.push([t.date,'Transfer in',t.reference||t.id,t.to,'',t.amount/100]);});return {title:'Account activity',headers:['Date','Type','Reference','Account','Debit (KSh)','Credit (KSh)'],money:[4,5],rows:rows.sort((a,b)=>b[0].localeCompare(a[0]))};}
  const t=totals();return {title:'School overview',subtitle:term,headers:['Indicator','Value'],rows:[['Active learners',state.students.filter(s=>s.status==='Active').length],['Expected fees (KSh)',t.target/100],['Collected fees (KSh)',t.collected/100],['Outstanding fees (KSh)',t.outstanding/100],['Collection rate',t.rate+'%'],['School balance (KSh)',totalBalance()/100],['Recorded expenses (KSh)',sum(state.expenses)/100],['Low-stock items',state.stock.filter(s=>s.quantity<=s.reorder).length]],money:[1]};
}
function csvCell(v){if(typeof v==='number')return Number.isFinite(v)?v.toFixed(2):'';let s=String(v??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportCSV(type){const d=dataset(type),csv=[d.headers,...d.rows].map(r=>r.map(csvCell).join(',')).join('\r\n');download('aic-shanzu-'+type+'-'+today()+'.csv','\uFEFF'+csv,'text/csv;charset=utf-8');toast('CSV exported · '+d.rows.length+' records');}
function printDoc(title,body,note='Demo workspace · sample records. This system-generated document is not a KRA tax invoice.'){
  $('#print-area').innerHTML=`<article class="print-document"><header class="print-letterhead"><img src="assets/crest-mark.svg" alt=""><div><h1>${esc(state.settings.school)}</h1><p>${esc(state.settings.address)}${state.settings.phone?' · '+esc(state.settings.phone):''}</p><p>${esc(state.settings.email)}</p></div></header><h2>${esc(title)}</h2>${body}<footer class="print-note">${esc(note)}<br>Prepared ${dateLabel(today())} · ${esc(state.settings.admin)}</footer></article>`;window.print();
}
function printTable(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function printReport(type){const d=dataset(type);printDoc(d.title,`<p class="muted">${esc(d.subtitle||'All records in this workspace')}</p>${printTable(d.headers,d.rows.map(r=>r.map((v,i)=>d.money?.includes(i)&&typeof v==='number'?money(Math.round(v*100)):v)))}`);}
function printReceipt(id){const p=state.payments.find(p=>p.id===id);if(!p)return;const i=invoice(p.invoiceId),s=student(p.studentId);printDoc('Fee payment receipt',`<dl class="detail-grid"><div><dt>Receipt number</dt><dd>${esc(p.id)}</dd></div><div><dt>Payment date</dt><dd>${dateLabel(p.date)}</dd></div><div><dt>Learner</dt><dd>${esc(s.name)} · ${esc(s.grade)}</dd></div><div><dt>Admission</dt><dd>${esc(s.id)}</dd></div><div><dt>Invoice</dt><dd>${esc(i.id)}</dd></div><div><dt>Term</dt><dd>${esc(i.term)} · ${i.year}</dd></div><div><dt>Method / reference</dt><dd>${esc(p.method)} · ${esc(p.reference)}</dd></div><div><dt>Received into</dt><dd>${esc(p.account)}</dd></div></dl><p>Amount received</p><div class="print-total money">${money(p.amount)}</div><p>Remaining invoice balance: <strong>${money(balance(i))}</strong></p><p style="margin-top:25px;font-size:12px">${esc(state.settings.receiptFooter)}</p>`);}
function printInvoice(id){const i=invoice(id);if(!i)return;const s=student(i.studentId),receipts=state.payments.filter(p=>p.invoiceId===id);printDoc('Fee statement · '+i.id,`<dl class="detail-grid"><div><dt>Learner</dt><dd>${esc(s.name)} · ${esc(s.grade)} ${esc(s.stream)}</dd></div><div><dt>Admission</dt><dd>${esc(s.id)}</dd></div><div><dt>Guardian</dt><dd>${esc(s.guardian)}</dd></div><div><dt>Term</dt><dd>${esc(i.term)} · ${i.year}</dd></div><div><dt>Issued</dt><dd>${dateLabel(i.issued)}</dd></div><div><dt>Due</dt><dd>${dateLabel(i.due)}</dd></div></dl>${printTable(['Description','Amount'],[[i.description,money(i.amount)]])}<p class="print-total">Balance due: ${money(balance(i))}</p><h3>Receipts · ${money(paid(i))}</h3>${receipts.length?printTable(['Date','Method','Reference','Amount'],receipts.map(p=>[dateLabel(p.date),p.method,p.reference,money(p.amount)])):'<p>No payments recorded.</p>'}`);}
function printPayslip(id){const s=state.staff.find(s=>s.id===id),e=state.expenses.find(e=>e.payrollId===id&&e.payrollPeriod===ui.payrollPeriod);if(!s||!e)return;printDoc('Payslip · '+monthLabel(ui.payrollPeriod),`<dl class="detail-grid"><div><dt>Staff member</dt><dd>${esc(s.name)}</dd></div><div><dt>Role</dt><dd>${esc(s.role)}</dd></div><div><dt>Payment date</dt><dd>${dateLabel(e.date)}</dd></div><div><dt>Reference</dt><dd>${esc(e.reference)}</dd></div></dl>${printTable(['Pay item','Amount (KSh)'],[['Gross pay',money(e.gross)],['PAYE',money(e.paye)],['NSSF employee deduction',money(e.nssf)],['SHIF',money(e.shif)],['Affordable Housing Levy',money(e.housing)]])}<p class="print-total">Net pay: ${money(e.amount)}</p>`,'Demo payroll record · deductions were entered manually, not calculated or certified. Not a statutory filing.');}
function printCBC(id){const s=student(id);if(!s)return;const rows=state.assessments.filter(a=>a.studentId===id&&a.term===state.settings.term&&a.year===state.settings.year);printDoc('Learner progress report · '+state.settings.term,`<dl class="detail-grid"><div><dt>Learner</dt><dd>${esc(s.name)}</dd></div><div><dt>Class</dt><dd>${esc(s.grade)} · ${esc(s.stream)}</dd></div><div><dt>Admission</dt><dd>${esc(s.id)}</dd></div><div><dt>Academic year</dt><dd>${state.settings.year}</dd></div></dl>${rows.length?printTable(['Learning area / strand','Level','Evidence & next steps','Date'],rows.map(a=>[a.area+' · '+a.strand,a.level+' · '+D.levels[a.level],a.comment,dateLabel(a.date)])):'<p>No observations recorded for this term.</p>'}<p style="font-size:12px;margin-top:20px">EE: Exceeding expectation · ME: Meeting expectation · AE: Approaching expectation · BE: Below expectation.</p>`,'School-based learning observations · not an official KNEC assessment report.');}
function printMessage(id){const m=state.messages.find(m=>m.id===id);if(!m)return;printDoc(m.title,`<p class="muted">${esc(m.audience)} · ${dateLabel(m.date)}</p><div class="print-message" style="margin-top:25px">${esc(m.body)}</div>`,'Prepared notice · not sent by this workspace.');}
async function copyMessage(id){const m=state.messages.find(m=>m.id===id);if(!m)return;try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(m.body);else{const t=document.createElement('textarea');t.value=m.body;t.style.cssText='position:fixed;left:-9999px';$('#modal-content').appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();if(!ok)throw Error('Copy unavailable');}toast('Notice copied. Paste it into your own messaging channel.');}catch(e){toast('Copy is unavailable in this browser. Use Print notice instead.',true);}}
function notifications(){const list=[],t=totals();if(t.unpaid)list.push({id:'fees-'+t.outstanding,title:money(t.outstanding)+' in outstanding fees',sub:t.unpaid+' learners · review fee statements',route:'fees',icon:'receipt'});state.stock.filter(s=>s.quantity<=s.reorder).forEach(s=>list.push({id:'stock-'+s.id+'-'+s.quantity,title:s.name+' is running low',sub:s.quantity+' '+s.unit+' remaining · reorder at '+s.reorder,route:'inventory',icon:'box'}));if(state.staff.some(s=>!staffPaid(s.id,state.settings.payday.slice(0,7))))list.push({id:'payroll-'+state.settings.payday,title:'Upcoming payroll · '+shortDate(state.settings.payday),sub:state.staff.length+' staff members · review deductions',route:'payroll',icon:'wallet'});state.awards.filter(a=>a.status==='Approved').forEach(a=>list.push({id:'bursary-'+a.id,title:'Bursary approved · '+student(a.studentId)?.name,sub:money(a.amount)+' · record the disbursement when received',route:'bursaries?id='+a.id,icon:'award'}));return list;}
function renderNotifications(){const list=notifications();$('#notifications').innerHTML=`<div class="popover-header"><h2>School updates</h2><button class="text-button" data-action="read-notifications">Mark all read</button></div>${list.length?list.map(n=>`<button class="notification-item" data-action="notification-route" data-id="${esc(n.id)}" data-route="${esc(n.route)}">${icon(n.icon)}<span><b>${esc(n.title)}${state.settings.readNotifications?.includes(n.id)?' <span class="muted">· read</span>':''}</b><small>${esc(n.sub)}</small></span></button>`).join(''):empty('All caught up','School updates will appear here.')}`;}
function searchIndex(){
  const items=navGroups.flatMap(g=>g.items.map(([route,title,ic])=>({title,sub:'Open workspace page',type:'Page',route,icon:ic,keywords:title})));
  state.students.forEach(s=>items.push({title:s.name,sub:s.id+' · '+s.grade+' '+s.stream,type:'Learner',route:'students?id='+s.id,icon:'students',keywords:[s.name,s.id,s.guardian,s.grade].join(' ')}));
  state.invoices.forEach(i=>items.push({title:student(i.studentId)?.name+' · '+i.id,sub:i.description+' · balance '+money(balance(i)),type:'Invoice',route:'fees?id='+i.id,icon:'receipt',keywords:[student(i.studentId)?.name,i.id,i.description].join(' ')}));
  state.payments.forEach(p=>items.push({title:student(p.studentId)?.name+' · '+money(p.amount),sub:p.reference+' · '+p.method+' · '+shortDate(p.date),type:'Payment',route:'fees?payment='+p.id,icon:'wallet',keywords:[student(p.studentId)?.name,p.reference,p.id,p.method].join(' ')}));
  state.staff.forEach(s=>items.push({title:s.name,sub:s.role,type:'Staff',route:'payroll?id='+s.id,icon:'wallet',keywords:s.name+' '+s.role}));
  state.expenses.forEach(e=>items.push({title:e.description,sub:e.category+' · '+money(e.amount),type:'Expense',route:'expenses?q='+encodeURIComponent(e.id),icon:'expenses',keywords:[e.description,e.vendor,e.id,e.category].join(' ')}));
  state.awards.forEach(a=>items.push({title:student(a.studentId)?.name+' · '+a.source,sub:money(a.amount)+' · '+a.status,type:'Bursary',route:'bursaries?id='+a.id,icon:'award',keywords:[student(a.studentId)?.name,a.source,a.reference,a.id].join(' ')}));
  state.routes.forEach(r=>items.push({title:r.name,sub:r.area,type:'Route',route:'transport?id='+r.id,icon:'bus',keywords:r.name+' '+r.area}));
  state.stock.forEach(s=>items.push({title:s.name,sub:s.quantity+' '+s.unit+' · '+s.category,type:'Stock',route:'inventory?id='+s.id,icon:'box',keywords:s.name+' '+s.category}));
  state.messages.forEach(m=>items.push({title:m.title,sub:m.audience+' · '+m.status,type:'Notice',route:'communications?id='+m.id,icon:'message',keywords:m.title+' '+m.body+' '+m.audience}));
  state.assessments.forEach(a=>items.push({title:student(a.studentId)?.name+' · '+a.area,sub:a.strand+' · '+a.level,type:'CBC',route:'cbc?id='+a.id,icon:'book',keywords:[student(a.studentId)?.name,a.area,a.strand,a.comment].join(' ')}));
  return items;
}
function highlight(text,q){const s=String(text||''),i=s.toLowerCase().indexOf(q.toLowerCase());return q&&i>=0?esc(s.slice(0,i))+'<mark>'+esc(s.slice(i,i+q.length))+'</mark>'+esc(s.slice(i+q.length)):esc(s);}
function renderSearch(){const q=$('#global-search').value.trim(),all=searchIndex();ui.searchItems=(q?all.filter(x=>x.keywords.toLowerCase().includes(q.toLowerCase())):all.filter(x=>x.type==='Page'&&['overview','students','fees','attendance','settings'].includes(x.route))).slice(0,12);ui.searchIndex=-1;$('#search-results').innerHTML=`<div class="search-heading">${q?'Matching records':'Quick navigation'}</div>${ui.searchItems.length?ui.searchItems.map((x,i)=>`<a class="search-result" role="option" aria-selected="false" id="search-option-${i}" href="#${esc(x.route)}" data-search-index="${i}">${icon(x.icon)}<div><b>${highlight(x.title,q)}</b><small>${highlight(x.sub,q)}</small></div><small>${x.type}</small></a>`).join(''):`<div class="search-empty">No matches for “${esc(q)}”.<br>Try a learner name, admission number or reference.</div>`}<div class="search-help">↑ ↓ to browse · Enter to open · Esc to close</div>`;$('#search-results').hidden=false;$('#global-search').setAttribute('aria-expanded','true');$('#global-search').removeAttribute('aria-activedescendant');}
function closeSearch(){$('#search-results').hidden=true;$('#global-search').setAttribute('aria-expanded','false');$('#global-search').removeAttribute('aria-activedescendant');ui.searchIndex=-1;}
function openDeepLink(){const p=ui.params;if(p.q){ui.filters[ui.route]={...ui.filters[ui.route],q:p.q};ui.pages[ui.route]=1;render();}if(p.payment){openPaymentDetail(p.payment);return;}if(!p.id)return;const actions={students:openStudentDetail,fees:openInvoiceDetail,payroll:id=>openForm('staff',id),bursaries:openBursaryDetail,transport:id=>openForm('route',id),inventory:id=>openForm('stock',id),communications:openMessageDetail,cbc:id=>openForm('assessment',id)};actions[ui.route]?.(p.id);}
function updatePaymentSummary(select){const inv=invoice(select.value);if(!inv)return;const amount=$('#f-amount');$('#payment-balance').textContent=money(balance(inv));amount.max=balance(inv)/100;amount.value=(balance(inv)/100).toFixed(2);}
function handleAction(button){
  const a=button.dataset.action,id=button.dataset.id;
  const forms={'add-payment':'payment','add-student':'student','edit-student':'student','add-invoice':'invoice','add-expense':'expense','add-staff':'staff','edit-staff':'staff','add-assessment':'assessment','edit-assessment':'assessment','add-bursary':'bursary','edit-bursary':'bursary','add-route':'route','edit-route':'route','assign-route':'assign','add-stock':'stock','edit-stock':'stock','add-message':'message','edit-message':'message','transfer':'transfer','opening-balances':'opening','pay-staff':'pay-staff'};
  if(forms[a]){openForm(forms[a],a.startsWith('edit-')||a==='pay-staff'?id:'',a==='assign-route'?id:'');return;}
  if(a==='close-modal'){closeModal();return;}
  if(a==='student-detail'){openStudentDetail(id);return;}
  if(a==='invoice-detail'){openInvoiceDetail(id);return;}
  if(a==='bursary-detail'){openBursaryDetail(id);return;}
  if(a==='message-detail'){openMessageDetail(id);return;}
  if(a==='payment-for'){openForm('payment','',id);return;}
  if(a==='invoice-for'){openForm('invoice','',id);return;}
  if(a==='receipt'){printReceipt(id);return;}
  if(a==='print-invoice'){printInvoice(id);return;}
  if(a==='payslip'){printPayslip(id);return;}
  if(a==='cbc-report'){printCBC(id);return;}
  if(a==='print-message'){printMessage(id);return;}
  if(a==='print-report'){printReport(button.dataset.type);return;}
  if(a==='print-attendance'){printReport('attendance');return;}
  if(a==='export'){exportCSV(button.dataset.type);return;}
  if(a==='copy-message'){copyMessage(id);return;}
  if(a==='prepare-message'){commit(s=>s.messages.find(m=>m.id===id).status='Prepared','Notice marked prepared');openMessageDetail(id);return;}
  if(a==='bursary-decision'){const status=button.dataset.status;if(status==='Approved'){const award=state.awards.find(a=>a.id===id);openModal('Record bursary approval',`<form data-form="bursary-approve">${hidden('id',id)}<div class="form-summary"><span>${esc(student(award.studentId).name)}</span><b>${money(award.amount)}</b></div>${input('reference','Funder award reference',award.reference,'text','required maxlength="80"')}${formActions('Record approval')}</form>`,'BURSARIES & SUPPORT');return;}commit(s=>s.awards.find(x=>x.id===id).status=status,'Bursary '+status.toLowerCase());openBursaryDetail(id);return;}
  if(a==='stock-move'){openForm('stock-move',id,button.dataset.direction);return;}
  if(a==='collapse-sidebar'){if(innerWidth<=760){closeMobile();return;}commit(s=>s.settings.sidebarCollapsed=!s.settings.sidebarCollapsed);return;}
  if(a==='nav-group'){const g=button.dataset.group;commit(s=>{s.settings.groups=s.settings.groups||{};s.settings.groups[g]=!s.settings.groups[g];});$(`[data-group="${g}"]`)?.focus();return;}
  if(a==='mobile-menu'){const open=document.body.classList.toggle('mobile-open');button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close navigation':'Open navigation');return;}
  if(a==='close-mobile'){closeMobile();return;}
  if(a==='notifications'){const open=$('#notifications').hidden;$('#notifications').hidden=!open;$('#notification-button').setAttribute('aria-expanded',String(open));if(open)renderNotifications();return;}
  if(a==='read-notifications'){commit(s=>s.settings.readNotifications=notifications().map(n=>n.id),'School updates marked read');renderNotifications();return;}
  if(a==='notification-route'){const route=button.dataset.route;commit(s=>{s.settings.readNotifications=[...new Set([...(s.settings.readNotifications||[]),id])];});$('#notifications').hidden=true;$('#notification-button').setAttribute('aria-expanded','false');navigate(route);return;}
  if(a==='page'){ui.pages[button.dataset.key]=Number(button.dataset.page);render();return;}
  if(a==='fee-tab'){ui.filters.fees={tab:button.dataset.tab};ui.pages.fees=1;render();return;}
  if(a==='chart-mode'){if(ui.route==='analytics')ui.analyticsMode=button.dataset.mode;else ui.chartMode=button.dataset.mode;render();return;}
  if(a==='chart-bar'){const key=button.dataset.chart,c=ui.charts[key],i=Number(button.dataset.index);c.selected=i;$$(`[data-chart="${key}"]`).forEach(b=>{const selected=Number(b.dataset.index)===i;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});const fmt=v=>c.unit==='money'?money(v):v+(c.unit==='percent'?'%':'');$('#chart-detail-'+key).textContent=`${c.labels[i]} · ${fmt(c.values[i])}${i>0?' · '+(c.values[i]===c.values[i-1]?'No change':c.values[i]>c.values[i-1]?'Increase':'Decrease')+' vs previous period':' · Baseline period'}`;return;}
  if(a==='attendance-mark'){ui.attendanceDraft[id]=button.dataset.value;$$('button',button.parentElement).forEach(b=>{const selected=b.dataset.value===button.dataset.value;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});$('#attendance-save-status').textContent='You have unsaved changes.';return;}
  if(a==='mark-all-present'){attendanceRows().forEach(s=>ui.attendanceDraft[s.id]='Present');render();toast('Filtered learners marked present. Save the register to keep these marks.');return;}
  if(a==='save-attendance'){const missing=state.students.filter(s=>s.status==='Active'&&!ui.attendanceDraft[s.id]);if(missing.length){toast(missing.length+' active learners still need a mark. Clear filters to find them.',true);return;}const date=ui.attendanceDate,register={...ui.attendanceDraft};commit(s=>s.attendance[date]=register,'Attendance saved · '+dateLabel(date));ui.attendanceDraft={...register};return;}
  if(a==='account-filter'){ui.filters.accounts={account:id};ui.pages.accounts=1;navigate('accounts');render();return;}
  if(a==='backup'){download('aic-shanzu-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');toast('Workspace backup exported. Keep it somewhere private.');return;}
  if(a==='import-backup'){$('#import-file').click();return;}
  if(a==='confirm-import'){if(!ui.pendingImport)return;const incoming=ui.pendingImport;commit(s=>{Object.keys(s).forEach(k=>delete s[k]);Object.assign(s,structuredClone(incoming));},'Workspace backup imported');ui.pendingImport=null;ui.attendanceDraft=null;ui.filters={};ui.pages={};closeModal();navigate('overview');render();toast('Workspace backup imported.');return;}
  if(a==='reset-demo'){openModal('Restore the sample workspace?',`<form data-form="reset">${notice('This replaces all records and settings in this browser with the original fictional sample data. Export a backup first if you need these records.',true)}<div class="form-field"><label for="f-confirm">Type RESET to confirm</label><input id="f-confirm" name="confirm" required pattern="RESET" autocomplete="off" placeholder="RESET"></div>${formActions('Restore sample data')}</form>`,'WORKSPACE DATA');return;}
}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(button){if(button.tagName==='A')event.preventDefault();handleAction(button);}
  const nav=event.target.closest('.nav-item');if(nav)closeMobile();
  if(event.target.closest('.search-result'))closeSearch();
  if(!event.target.closest('.universal-search'))closeSearch();
  if(!event.target.closest('.notification-wrap')){$('#notifications').hidden=true;$('#notification-button').setAttribute('aria-expanded','false');}
});
document.addEventListener('submit',handleSubmit);
document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search'){renderSearch();return;}if(el.dataset.filter){const [key,name]=el.dataset.filter.split(':');ui.filters[key]={...ui.filters[key],[name]:el.value};ui.pages[key]=1;render();}});
document.addEventListener('change',async event=>{
  const el=event.target;
  if(el.dataset.filter){const [key,name]=el.dataset.filter.split(':');ui.filters[key]={...ui.filters[key],[name]:el.value};ui.pages[key]=1;render();}
  if(el.dataset.setting){const name=el.dataset.setting,value=el.checked;commit(s=>{if(name==='expanded')s.settings.sidebarCollapsed=!value;else s.settings[name]=value;},'Workspace preference updated');}
  if(el.id==='attendance-date'){if(!validDate(el.value)||el.value>today()){el.value=ui.attendanceDate;toast('Choose a valid register date, no later than today.',true);return;}ui.attendanceDrafts[ui.attendanceDate]={...ui.attendanceDraft};ui.attendanceDate=el.value;ui.attendanceDraft=ui.attendanceDrafts[el.value]?{...ui.attendanceDrafts[el.value]}:null;render();}
  if(el.id==='payroll-period'){ui.payrollPeriod=el.value;ui.pages.payroll=1;render();}
  if(el.id==='f-invoiceId'&&el.closest('[data-form="payment"]'))updatePaymentSummary(el);
  if(el.id==='f-template'&&el.value){$('#f-body').value=templates[el.value];if(!$('#f-title').value)$('#f-title').value={fee:'Term fee reminder',attendance:'Attendance follow-up',meeting:'Parent and teacher meeting'}[el.value];}
  if(el.id==='import-file'){
    const file=el.files?.[0];el.value='';if(!file)return;
    try{if(file.size>5000000)throw Error('Choose a backup smaller than 5 MB.');const incoming=JSON.parse(await file.text());validateState(incoming);ui.pendingImport=incoming;openModal('Replace this workspace?',`<div class="form-summary"><span>${esc(incoming.settings.school)}</span><b>${incoming.students.length} learners · ${incoming.payments.length} payments</b></div>${notice('Importing replaces the current browser workspace. Export your current records first if you need them.',true)}<div class="form-actions"><button class="button secondary" data-action="backup">Export current records</button><button class="button primary" data-action="confirm-import">${icon('upload')}Replace & import</button></div>`,'WORKSPACE BACKUP');}catch(error){ui.pendingImport=null;toast('Import failed: '+error.message,true);}
  }
});
$('#global-search').addEventListener('focus',renderSearch);
document.addEventListener('keydown',event=>{
  if($('#modal').open)return;
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#global-search').focus();$('#global-search').select();return;}
  if(event.key==='Escape'){closeSearch();closeMobile();$('#notifications').hidden=true;$('#notification-button').setAttribute('aria-expanded','false');return;}
  if(document.activeElement===$('#global-search')&&!$('#search-results').hidden&&['ArrowDown','ArrowUp','Enter'].includes(event.key)){
    event.preventDefault();if(event.key==='Enter'){const item=$(`#search-option-${Math.max(0,ui.searchIndex)}`);if(item)item.click();return;}
    const count=ui.searchItems.length;if(!count)return;ui.searchIndex=(ui.searchIndex+(event.key==='ArrowDown'?1:-1)+count)%count;$$('.search-result').forEach((el,i)=>{el.classList.toggle('selected',i===ui.searchIndex);el.setAttribute('aria-selected',String(i===ui.searchIndex));});const selected=$(`#search-option-${ui.searchIndex}`);$('#global-search').setAttribute('aria-activedescendant',selected.id);selected.scrollIntoView({block:'nearest'});
  }
});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{closeModal();parseRoute();closeMobile();closeSearch();render();$('#main').focus({preventScroll:true});openDeepLink();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('resize',()=>{if(innerWidth>760)closeMobile();});
window.addEventListener('storage',event=>{if(event.key===STORAGE&&event.newValue){try{const next=JSON.parse(event.newValue);validateState(next);state=next;ui.attendanceDraft=null;render();toast('Workspace updated from another tab.');}catch(e){toast('Another tab saved incompatible data. Export a backup before continuing.',true);}}});
parseRoute();render();openDeepLink();
